      ? scholarship.toObject()
      : scholarship;

  setImmediate(() => {
    notifyUsersOfNewScholarship(payload).catch((err) =>
      console.error(`${LOG_PREFIX} Unhandled hook error:`, err.message),
    );
  });
}
